{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE MapleMonk.Meta_And_Google_Detailed AS WITH Marketing_Granular AS ( SELECT DATE, SUM(CASE WHEN UPPER(CHANNEL) = \'FACEBOOK\' THEN IFNULL(SPEND, 0) ELSE 0 END) AS Meta_Spend, SUM(CASE WHEN UPPER(CHANNEL) = \'GOOGLE\' THEN IFNULL(SPEND, 0) ELSE 0 END) AS Google_Spend, SUM(Landing_Page_Views) AS Landing_Page_Views, SUM(Add_to_carts) AS Add_To_Carts, SUM(Initiate_Checkouts) AS Initiate_Checkouts, sum(case when lower(replace(ifnull(campaign_name,\'\'),\'_\',\'$\')) like any(\'%$top$%\',\'%insta%\',\'%madison$zouk%\') then ifnull(spend,0) else 0 end) as M_Spend, sum(case when lower(replace(ifnull(campaign_name,\'\'),\'_\',\'$\')) like \'%social$yt%\' OR lower(campaign_name) like \'demand gen- myntra\' then ifnull(spend,0) else 0 end) as G_Spend, SUM(CASE WHEN LOWER(REPLACE(IFNULL(CAMPAIGN_NAME,\'\'),\'_\',\'$\')) NOT LIKE \'%social$yt%\' AND UPPER(CHANNEL) LIKE \'GOOGLE\' THEN IFNULL(Impressions, 0) ELSE 0 END) AS G_impressions, SUM(CASE WHEN LOWER(CAMPAIGN_NAME) NOT LIKE \'%instagram%\' AND UPPER(CHANNEL) LIKE \'FACEBOOK\' THEN IFNULL(Impressions, 0) ELSE 0 END) AS M_impressions, SUM(CASE WHEN LOWER(REPLACE(IFNULL(CAMPAIGN_NAME,\'\'),\'_\',\'$\')) NOT LIKE \'%social$yt%\' AND UPPER(CHANNEL) LIKE \'GOOGLE\' THEN IFNULL(Link_Clicks, 0) ELSE 0 END) AS GL_Clicks, SUM(CASE WHEN LOWER(CAMPAIGN_NAME) NOT LIKE \'%instagram%\' AND UPPER(CHANNEL) LIKE \'FACEBOOK\' THEN IFNULL(Link_Clicks, 0) ELSE 0 END) AS ML_Clicks, SUM(CASE WHEN LOWER(REPLACE(IFNULL(CAMPAIGN_NAME,\'\'),\'_\',\'$\')) NOT LIKE \'%social$yt%\' AND UPPER(CHANNEL) LIKE \'GOOGLE\' THEN IFNULL(Landing_Page_Views, 0) ELSE 0 END) AS G_LPV, SUM(CASE WHEN LOWER(CAMPAIGN_NAME) NOT LIKE \'%instagram%\' AND UPPER(CHANNEL) LIKE \'FACEBOOK\' THEN IFNULL(Landing_Page_Views, 0) ELSE 0 END) AS M_LPV FROM `MapleMonk.zouk_MARKETING_CONSOLIDATED` GROUP BY 1 ), Sales_Performance AS ( SELECT Date, SUM(Net_Revenue) AS Sales, SUM(Brand_Spend) AS Brand_Spend, SUM(Spend) AS Spend, SUM(Other_Perf_Spend) AS Other_Perf_Spends, SUM(Orders) AS Total_Orders, SUM(IFNULL(Web_Sessions, 0) + IFNULL(App_Sessions, 0)) AS Total_Sessions FROM `MapleMonk.Zouk_D2C_Sessions_Report` GROUP BY 1 ) SELECT m.Date, IFNULL(m.M_Spend,0) AS M_Spend, IFNULL(m.G_Spend,0) AS G_Spend, (m.M_Spend + m.G_Spend) AS Brand_Total_Spends, (m.Meta_Spend - m.M_Spend) AS Meta_Spend, (m.Google_Spend - m.G_Spend) AS Google_Spend, (m.Meta_Spend - m.M_Spend + m.Google_Spend - m.G_Spend) AS Total_Spend, IFNULL(m.ML_Clicks,0) AS ML_Clicks, IFNULL(m.GL_Clicks,0) AS GL_Clicks, (m.ML_Clicks + m.GL_Clicks) AS Link_Clicks, IFNULL(m.M_Impressions,0) AS Meta_Impressions, IFNULL(m.G_Impressions,0) AS Google_Impressions, (m.M_Impressions + m.G_Impressions) AS Impressions, IFNULL(m.Landing_Page_Views, 0) AS Landing_Page_Views, IFNULL(m.Add_To_Carts, 0) AS Add_To_Carts, IFNULL(m.Initiate_Checkouts, 0) AS Initiate_Checkouts, IFNULL(s.Sales, 0) AS Sales, IFNULL(s.Brand_Spend, 0) AS Brand_Spend, IFNULL(s.Spend, 0) AS Spend, IFNULL(s.Other_Perf_Spends, 0) AS Other_Perf_Spends, IFNULL(s.Total_Orders, 0) AS Orders, IFNULL(s.Total_Sessions, 0) AS Sessions FROM Marketing_Granular m LEFT JOIN Sales_Performance s ON m.Date = s.Date WHERE m.Meta_Spend > 0 OR m.Google_Spend > 0 OR m.M_Spend > 0 OR m.G_Spend > 0 ORDER BY m.Date DESC;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            